    58	  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
    59	  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
    60	  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
    61	  latestFor?(userId: string | number): Awaitable<T | undefined>;
    62	  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
    63	  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
    64	}

